fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut low = 0;
    let mut high = v.len() - 1;

    while low < high {
        let mid = low + (high - low) / 2;

        if v[mid] < k {
            low = mid + 1;
        } else {
            high = mid; // Keep mid because v[mid] could be == k
        }
    }

    // Here low == high, and v[low] == k guaranteed by assumption.
    low
}